CREATE TABLE IF NOT EXISTS migrations(version integer PRIMARY KEY, applied_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password text NOT NULL, owner boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token text PRIMARY KEY, user_id uuid REFERENCES users ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(token text PRIMARY KEY, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS application_settings(key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS photos(id uuid PRIMARY KEY, filename text NOT NULL, mime text NOT NULL, sha256 text UNIQUE NOT NULL, size bigint NOT NULL, width integer, height integer, capture_local text NOT NULL, capture_source text NOT NULL DEFAULT 'upload', capture_offset text, uploader uuid REFERENCES users, status text NOT NULL DEFAULT 'pending', error text, featured boolean DEFAULT false, uploaded_at timestamptz DEFAULT now(), deleted_at timestamptz);
CREATE INDEX IF NOT EXISTS photos_cursor ON photos(capture_local DESC,id DESC) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS photo_metadata(photo_id uuid PRIMARY KEY REFERENCES photos ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS albums(id uuid PRIMARY KEY, title text NOT NULL, description text DEFAULT '', location text DEFAULT '', date text, cover uuid REFERENCES photos ON DELETE SET NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS album_photos(album_id uuid REFERENCES albums ON DELETE CASCADE, photo_id uuid REFERENCES photos ON DELETE CASCADE, PRIMARY KEY(album_id,photo_id));
CREATE TABLE IF NOT EXISTS favorites(user_id uuid REFERENCES users ON DELETE CASCADE, photo_id uuid REFERENCES photos ON DELETE CASCADE, PRIMARY KEY(user_id,photo_id));
CREATE TABLE IF NOT EXISTS photo_comments(id uuid PRIMARY KEY, photo_id uuid REFERENCES photos ON DELETE CASCADE, user_id uuid REFERENCES users, body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS photo_views(user_id uuid REFERENCES users ON DELETE CASCADE,photo_id uuid REFERENCES photos ON DELETE CASCADE,PRIMARY KEY(user_id,photo_id));
CREATE TABLE IF NOT EXISTS studio_drafts(id uuid PRIMARY KEY,title text NOT NULL,notes text DEFAULT '',creator uuid REFERENCES users,status text NOT NULL DEFAULT 'collecting',caption text DEFAULT '',hashtags text DEFAULT '',ratio text DEFAULT '4:5',fit text DEFAULT 'contain',version integer DEFAULT 1,post_url text DEFAULT '',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS studio_draft_photos(draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,photo_id uuid REFERENCES photos ON DELETE CASCADE,position integer NOT NULL,PRIMARY KEY(draft_id,photo_id),UNIQUE(draft_id,position));
CREATE TABLE IF NOT EXISTS studio_photo_suggestions(draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,photo_id uuid REFERENCES photos ON DELETE CASCADE,user_id uuid REFERENCES users,created_at timestamptz DEFAULT now(),PRIMARY KEY(draft_id,photo_id,user_id));
CREATE TABLE IF NOT EXISTS draft_comments(id uuid PRIMARY KEY,draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,photo_id uuid REFERENCES photos ON DELETE CASCADE,user_id uuid REFERENCES users,body text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS caption_versions(id uuid PRIMARY KEY,draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,user_id uuid REFERENCES users,body text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS song_suggestions(id uuid PRIMARY KEY,draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,user_id uuid REFERENCES users,title text NOT NULL,artist text DEFAULT '',link text DEFAULT '',notes text DEFAULT '',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS draft_approvals(draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,user_id uuid REFERENCES users,version integer NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(draft_id,user_id));
CREATE TABLE IF NOT EXISTS upload_sessions(id uuid PRIMARY KEY,user_id uuid REFERENCES users,filename text NOT NULL,size bigint NOT NULL,offset_bytes bigint DEFAULT 0,state text DEFAULT 'uploading',photo_id uuid REFERENCES photos ON DELETE SET NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS processing_jobs(id uuid PRIMARY KEY,photo_id uuid UNIQUE REFERENCES photos ON DELETE CASCADE,state text DEFAULT 'pending',attempts integer DEFAULT 0,error text,updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS export_jobs(id uuid PRIMARY KEY,draft_id uuid REFERENCES studio_drafts ON DELETE CASCADE,version integer NOT NULL,state text DEFAULT 'pending',error text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,user_id uuid REFERENCES users,event text NOT NULL,created_at timestamptz DEFAULT now());
INSERT INTO migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
